sap.ui.define(["sap/ui/core/mvc/Controller","sap/ui/model/json/JSONModel","be/kuleuven/application/model/services","sap/ui/core/UIComponent"],function(e,t,o,n){"use strict";return e.extend("be.kuleuven.application.controller.Scholarships",{scholarModel:new t,prevScholarModel:new t,account:null,onInit:function(){this.getView().setModel(this.scholarModel,"scholarModel");this.getView().setModel(this.prevScholarModel,"prevScholarModel");n.getRouterFor(this).getRoute("scholarships").attachPatternMatched(this.onRouteMatched,this)},onRouteMatched:function(e){o.setModel(this.getView().getModel());var t=this;this.account=e.getParameter("arguments").account;o.getScholarships(this.account).then(function(e){t.scholarModel.setData(e)});o.getPrevScholarships(this.account).then(function(e){t.prevScholarModel.setData(e)})},onNavBack:function(){var e=n.getRouterFor(this);e.myNavBack("main")},changeLanguage:function(e){if(e.getSource().getText()==="EN"){sap.ui.getCore().getConfiguration().setLanguage("en-EN")}else if(e.getSource().getText()==="NL"){sap.ui.getCore().getConfiguration().setLanguage("nl-NL")}},onLogOutPress:function(e){if(window.location.hostname.indexOf("webwsp")>=0){window.location.replace("https://idp.kuleuven.be/idpx/profile/Logout","_blank")}else if(window.location.hostname.indexOf("webwsq")>=0){window.location.replace("https://idp.q.icts.kuleuven.be/idpx/profile/Logout","_blank")}else{window.location.replace("https://idp.kuleuven.be/idpx/profile/Logout","_blank")}},onAddScholarship:function(e){var t=this.getView().getModel("prevScholarModel");var o=t.getData();o.push({});t.setData(o)},onDeletePress:function(e){var t=e.getSource();if(t.getItems().length>1){t.removeItem(e.getParameters().listItem)}}})});